    expect(decoded[0].operands.empty(), "CDQE unexpectedly has explicit operands");
    expect(rosa::debug::dumpX86(decoded).find("cdqe") != std::string::npos, "CDQE dump differs");

    const rosa::dbt::Translator translator;
